/* This sample uses a POSIX timer from the openvela/NuttX application layer.
 *
 * STM32 HAL mental model:
 *   HAL_TIM_Base_Start_IT()        -> timer_settime()
 *   HAL_TIM_PeriodElapsedCallback -> sigwaitinfo() returns a timer signal
 *
 * The low-level STM32 tick/interrupt work is owned by the kernel and BSP.
 * Application code asks the OS for periodic notifications, then handles each
 * tick in normal task context instead of inside a hardware interrupt callback.
 */

#define FIRST_LED BOARD_LED_GREEN
#define LED_TIMER_SIGNAL SIGRTMIN
#define LED_TIMER_INTERVAL_MS 500

/* Convert milliseconds to the timespec format used by POSIX timers. */

static void set_ms(struct timespec *ts, long ms)
{
  ts->tv_sec = ms / 1000;
  ts->tv_nsec = (ms % 1000) * 1000 * 1000;
}

int main(int argc, char *argv[])
{
  struct itimerspec timeout;
  struct sigevent event;
  siginfo_t info;
  sigset_t set;
  timer_t timerid;
  uint32_t nleds;
  bool ledon = false;
  int ret;

  /* Enable direct application control of the board LED GPIOs. This requires
   * CONFIG_ARCH_LEDS to be disabled, otherwise the board auto-LED logic owns
   * these LEDs and board_userled() is not linked into the firmware.
   */

  nleds = board_userled_initialize();
  if (nleds == 0)
    {
      printf("first_led: no user LEDs available\n");
      return 1;
    }

