#include <stdbool.h>
#include <errno.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <signal.h>
#include <time.h>

#include <arch/board/board.h>
#include <nuttx/board.h>

/* 这个例子使用 openvela/NuttX 应用层的 POSIX 定时器。
 *
 * 可以先用 STM32 HAL 的经验这样类比：
 *   HAL_TIM_Base_Start_IT()        -> timer_settime()
 *   HAL_TIM_PeriodElapsedCallback -> sigwaitinfo() 收到定时器信号
 *
 * STM32 底层 tick/中断由内核和 BSP 管理。应用代码只向 OS 申请周期通知，
 * 然后在普通任务上下文处理每个 tick，而不是在硬件中断回调里干活。
 */

#define FIRST_LED BOARD_LED_GREEN
#define LED_TIMER_SIGNAL SIGRTMIN
#define LED_TIMER_INTERVAL_MS 500

/* 把毫秒转换成 POSIX 定时器使用的 timespec 格式。 */

static void set_ms(struct timespec *ts, long ms)
{
  ts->tv_sec = ms / 1000;
  ts->tv_nsec = (ms % 1000) * 1000 * 1000;
}

int main(int argc, char *argv[])
{
  /* 下面 5 个变量就是这个 POSIX timer 示例的核心状态：
   *
   * timeout : 定时器的时间参数，传给 timer_settime()。
   *           timeout.it_value    表示第一次多久后触发。
   *           timeout.it_interval 表示后面每隔多久重复触发。
   *
   * event   : 定时器的通知方式，传给 timer_create()。
   *           这里配置为“超时后给当前任务发送 LED_TIMER_SIGNAL 信号”，
   *           并用 sival_int 顺手携带周期毫秒数，方便打印日志。
   *
   * info    : sigwaitinfo() 返回时填充的信号详情。
   *           本例用 info.si_value.sival_int 取出 event 里塞进去的周期值。
   *
   * set     : 信号集合。这里集合里只放 LED_TIMER_SIGNAL。
   *           它先用于 sigprocmask() 屏蔽这个信号，再用于 sigwaitinfo()
   *           指定“我只等这个定时器信号”。
   *
   * timerid : 内核创建定时器后返回的句柄。
   *           后面启动 timer_settime()、出错清理 timer_delete() 都靠它。
   */

  struct itimerspec timeout;
  struct sigevent event;
  siginfo_t info;
  sigset_t set;
  timer_t timerid;
  uint32_t nleds;
  bool ledon = false;
  int ret;

  /* 初始化板级用户 LED，让应用可以直接控制 LED GPIO。
   *
   * 这里要求 CONFIG_ARCH_LEDS 关闭；否则板级 auto-LED 逻辑会接管这些 LED，
   * board_userled() 也不会被链接进固件。
   */

  nleds = board_userled_initialize();
  if (nleds == 0)
    {
      printf("first_led: no user LEDs available\n");
      return 1;
    }

  /* 让定时器超时事件以实时信号的形式送到当前任务。
   *
   * 先把这个信号 block 住，这样它不会异步打断程序去跑 signal handler；
   * 信号会保持 pending 状态，直到主循环用 sigwaitinfo() 主动取走。
   */

  sigemptyset(&set);
  sigaddset(&set, LED_TIMER_SIGNAL);

  ret = sigprocmask(SIG_BLOCK, &set, NULL);
  if (ret < 0)
    {
      printf("first_led: sigprocmask failed, errno=%d\n", errno);
      return 1;
    }

  /* 描述定时器超时时如何通知应用。
   *
   * 当前配置可用的是 SIGEV_SIGNAL。这里故意不用 SIGEV_THREAD，因为当前
   * 板级配置没有打开 CONFIG_SIG_EVTHREAD。
   */

  memset(&event, 0, sizeof(event));
  event.sigev_notify = SIGEV_SIGNAL;
  event.sigev_signo = LED_TIMER_SIGNAL;
  event.sigev_value.sival_int = LED_TIMER_INTERVAL_MS;

  /* 创建一个由内核维护的软件定时器。
   *
   * CLOCK_MONOTONIC 表示从系统启动后开始递增的时间，不受校时影响，
   * 很适合 LED 闪烁这类周期任务。
   */

  ret = timer_create(CLOCK_MONOTONIC, &event, &timerid);
  if (ret < 0)
    {
      printf("first_led: timer_create failed, errno=%d\n", errno);
      return 1;
    }

  /* 启动定时器。
   *
   * it_value 是第一次超时时间；it_interval 是后续自动重装载周期。
   * 所以这里会每 500 ms 收到一次定时器信号。
   */

  set_ms(&timeout.it_value, LED_TIMER_INTERVAL_MS);
  set_ms(&timeout.it_interval, LED_TIMER_INTERVAL_MS);

  ret = timer_settime(timerid, 0, &timeout, NULL);
  if (ret < 0)
    {
      printf("first_led: timer_settime failed, errno=%d\n", errno);
      timer_delete(timerid);
      return 1;
    }

  printf("first_led: POSIX timer started, period=%d ms\n",
         LED_TIMER_INTERVAL_MS);

  for (; ; )
    {
      /* 同步等待下一次定时器 tick。
       *
       * 这样 LED 翻转和 printf() 都运行在普通任务上下文，不在中断上下文。
       */

      ret = sigwaitinfo(&set, &info);
      if (ret < 0)
        {
          printf("first_led: sigwaitinfo failed, errno=%d\n", errno);
          timer_delete(timerid);
          return 1;
        }

      ledon = !ledon;
      board_userled(FIRST_LED, ledon);
      printf("first_led: tick %d ms, green led %s\n",
             info.si_value.sival_int, ledon ? "on" : "off");
    }
}
